/**
 * Round 5 (owner tests 06-09): exam-precision-v1 — short responses with probes of accepted variants and real mistakes.
 *
 *   npm run bench:precision              build benchmarks/datasets/exam-precision-v1/items-{t2,t1a,gt1}.jsonl
 *   npm run bench:precision -- --check   fail if the files on disk differ from a fresh build
 *
 * Source: benchmarks/sources/precision-v1.json (generated by benchmarks/precision/source.py, texts written in the session).
 * expected.probes: [{id, kind: valid|error, class, named?, start, end, sentence: {start, end}, accepted?}] in code points of the
 * normalized text, as the backend counts them; expected.errors repeats the error probes for the usual recall metric.
 */
import {existsSync, mkdirSync, readFileSync, writeFileSync} from 'node:fs';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {chartBrief, checkNumbers, codePointLength, countWords, letterFacts, normalizeResponse, sliceCodePoints, type ChartSpec} from '../../packages/exam-domain/src/index.js';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');

type Task = 't2' | 't1a' | 'gt1';
interface SourceProbe { id: string; kind: 'valid' | 'error'; quote: string; sentence: string; class: string; named?: boolean; accepted?: string[] }
interface SourceItem { id: string; task: Task; ref: string; text: string; probes: SourceProbe[] }
export interface Probe { id: string; kind: 'valid' | 'error'; class: string; named?: boolean; start: number; end: number; sentence: {start: number; end: number}; accepted?: string[] }

const LIBRARY: Record<Task, string> = {
  t2: 'ielts-writing-task-2.v1.json', t1a: 'ielts-writing-task-1-academic.v1.json', gt1: 'ielts-writing-task-1-general.v1.json',
};
const MIN_WORDS: Record<Task, number> = {t2: 250, t1a: 150, gt1: 150};

/** Code-point offset of the only occurrence of `needle` in `text` after code-point offset `from`. */
function only(text: string, needle: string, from = 0, to = codePointLength(text)): number {
  const scope = sliceCodePoints(text, from, to);
  const at = scope.indexOf(needle);
  if (at < 0 || scope.indexOf(needle, at + 1) >= 0) throw new Error(`"${needle}" must occur exactly once`);
  return from + codePointLength(scope.slice(0, at));
}

export function buildPrecision(source: {items: SourceItem[]}): Record<Task, object[]> {
  const out: Record<Task, object[]> = {t2: [], t1a: [], gt1: []};
  for (const item of source.items) {
    const library = JSON.parse(readFileSync(join(root, 'packages/exam-domain/library', LIBRARY[item.task]), 'utf8'));
    const task = library.tasks.find((t: {ref: string}) => t.ref === item.ref);
    if (!task) throw new Error(`${item.id}: no library task ${item.ref}`);
    const text = normalizeResponse(item.text);
    if (countWords(text) < MIN_WORDS[item.task]) throw new Error(`${item.id}: ${countWords(text)} words, below ${MIN_WORDS[item.task]}`);
    const probes: Probe[] = item.probes.map(p => {
      const s = only(text, p.sentence);
      const e = s + codePointLength(p.sentence);
      const start = only(text, p.quote, s, e);
      for (const a of p.accepted ?? []) if (a === p.sentence) throw new Error(`${item.id}/${p.id}: an accepted sentence equals the original`);
      return {id: p.id, kind: p.kind, class: p.class, ...(p.named !== undefined ? {named: p.named} : {}), start, end: start + codePointLength(p.quote),
        sentence: {start: s, end: e}, ...(p.accepted ? {accepted: p.accepted} : {})};
    });
    const errors = probes.filter(p => p.kind === 'error').map(p => ({start: p.start, end: p.end, skill: p.class, severity: 'moderate', probe: p.id}));
    const base = {id: item.id, set: 'P', split: 'dev', examKey: item.task === 'gt1' ? 'ielts-general-training' : 'ielts-academic'};
    const spec = task.stimulus as ChartSpec | undefined;
    if (item.task === 'gt1' && letterFacts(text, task.stimulus.tone).mismatches.length) throw new Error(`${item.id}: the letter check is not clean`);
    out[item.task].push({
      ...base, ...(item.task === 't2' ? {} : {taskKey: 'task-1'}), taskRef: item.ref, prompt: task.text,
      ...(item.task === 't1a' ? {stimulus: spec, visual: chartBrief(spec!)} : item.task === 'gt1' ? {stimulus: task.stimulus} : {}),
      text,
      expected: {errors, probes, ...(item.task === 't1a' ? {numbers: {unmatched: checkNumbers(text, spec!).filter(m => m.status === 'unmatched')
        .map(m => ({start: m.start, end: m.end, text: m.text}))}} : {})},
      source: {written: 'session', round: '5'},
    });
  }
  return out;
}

function main(check: boolean): void {
  const source = JSON.parse(readFileSync(join(root, 'benchmarks/sources/precision-v1.json'), 'utf8'));
  const built = buildPrecision(source);
  let stale = false;
  for (const [task, items] of Object.entries(built)) {
    const path = join(root, `benchmarks/datasets/exam-precision-v1/items-${task}.jsonl`);
    const jsonl = items.map(i => JSON.stringify(i)).join('\n') + '\n';
    const probes = items.flatMap(i => (i as {expected: {probes: Probe[]}}).expected.probes);
    console.log(`exam-precision-v1 ${task}: ${items.length} items, ${probes.filter(p => p.kind === 'valid').length} valid, ${probes.filter(p => p.kind === 'error').length} errors`);
    for (const i of items as {id: string; expected: {numbers?: {unmatched: {text: string}[]}}}[]) {
      if (i.expected.numbers?.unmatched.length) console.log(`  ${i.id}: figures the code check finds in no value: ${i.expected.numbers.unmatched.map(u => u.text).join(', ')}`);
    }
    if ((existsSync(path) ? readFileSync(path, 'utf8') : null) === jsonl) continue;
    if (check) {
      console.error(`out of date: ${path}`);
      stale = true;
      continue;
    }
    mkdirSync(dirname(path), {recursive: true});
    writeFileSync(path, jsonl);
  }
  if (stale) process.exit(1);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main(process.argv.includes('--check'));
}
